import { Address, toNano } from "locklift";
import { factorySource } from "../build/factorySource";

const ST_EVER_VAULT_ADDRESS = new Address("0:675a6d63f27e3f24d41d286043a9286b2e3eb6b84fa4c3308cc2833ef6f54d68");
const CLUSTER_ADDRESS = new Address("0:03a72468e6dc4f0fdb3653f9cf0e198abce258cb4f533ba49cfe34eecb82396c");
const OWNER_ADDRESS = new Address("0:6bdca077c52d5dc7e75dc94c3f06a2700c76d8c9100162681e125fcca5120a2d");
const main1 = async () => {
  locklift.network.insertAccount({
    boc: "",
    address: ST_EVER_VAULT_ADDRESS,
    type: "accountStuffBoc",
    abi: factorySource.StEverVault_new,
  });

  locklift.network.insertAccount({
    boc: "",
    address: CLUSTER_ADDRESS,
    type: "accountStuffBoc",
    abi: factorySource.StEverCluster_new,
  });

  locklift.network.insertWallet(OWNER_ADDRESS);

  console.log(await locklift.provider.getBalance(OWNER_ADDRESS));
  // locklift.network.insertAccount({
  //
  // })
  const stEverContact = locklift.factory.getDeployedContract("StEverVault", ST_EVER_VAULT_ADDRESS);

  {
    const { traceTree } = await locklift.tracing.trace(
      stEverContact.methods
        .setNewClusterCode({
          _newClusterCode: locklift.factory.getContractArtifacts("StEverCluster").code,
        })
        .send({
          from: OWNER_ADDRESS,
          amount: toNano(10),
        }),
    );

    await traceTree?.beautyPrint();
  }

  {
    const { traceTree } = await locklift.tracing.trace(
      stEverContact.methods
        .upgradeStEverClusters({
          _clusters: [CLUSTER_ADDRESS],
          _sendGasTo: OWNER_ADDRESS,
        })
        .send({
          from: OWNER_ADDRESS,
          amount: toNano(10),
        }),
    );

    await traceTree?.beautyPrint();
  }
  {
    const { traceTree } = await locklift.tracing.trace(
      stEverContact.methods
        .dropCluster({
          _cluster: CLUSTER_ADDRESS,
          remainingGasTo: OWNER_ADDRESS,
          _isPunish: false,
        })
        .send({
          from: OWNER_ADDRESS,
          amount: toNano(15),
        }),
    );

    await traceTree?.beautyPrint();
  }
};

main1()
  .then(() => {
    console.log("Upgrade test completed successfully.");
  })
  .catch(error => {
    console.error("Error during upgrade test:", error);
  });
